// Lit un nombre, même s'il arrive en texte (« 1 250 », « 12,5 »)
function num(v) {
  if (typeof v === 'number') return v;
  if (v === undefined || v === null || v === '') return 0;
  const s = String(v).replace(/\s/g, '').replace(',', '.');
  const n = parseFloat(s.replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? 0 : n;
}

// DateTime (Luxon) est fourni directement par n8n
// WhatsApp (modèles Meta) : pas de retour à la ligne ni de case vide dans les variables
function wa(v) {
  const s = String(v ?? '').replace(/[\n\r\t]+/g, ' ').replace(/ {2,}/g, ' ').trim();
  return s === '' ? '-' : s.slice(0, 900);
}

// Les dates Google Sheets arrivent en « numéro de série » (jours depuis le 30/12/1899)
const base = DateTime.fromISO('1899-12-30', { zone: $now.zone });
const aujourdhui = Math.round($now.startOf('day').diff(base, 'days').days);
function jour(v) {
  if (typeof v === 'number') return Math.floor(v);
  const d = DateTime.fromISO(String(v).replace(' ', 'T'), { zone: $now.zone });
  return d.isValid ? Math.round(d.startOf('day').diff(base, 'days').days) : null;
}

const commandes = $('Lire les commandes').all().map(i => i.json)
  .filter(c => c['Code produit'] && jour(c['Date']) === aujourdhui && c['Statut'] !== 'Annulée');
const total = commandes.reduce((s, c) => s + num(c['Montant']), 0);
const marge = commandes.reduce((s, c) => s + num(c['Montant']) - num(c["Coût d'achat"]), 0);
const nonLivrees = commandes.filter(c => c['Statut'] === 'Nouvelle').length;

const produits = $input.all().map(i => i.json).filter(p => p['Code']);
const rupture = produits.filter(p => p['État'] === 'Rupture').map(p => `- ${p['Produit']}`);
const aCommander = produits.filter(p => p['État'] === 'À commander')
  .map(p => `- ${p['Produit']} (reste ${num(p['Stock actuel'])})`);

return [{ json: {
  jour: wa($now.toFormat('dd/MM/yyyy')),
  nb: wa(commandes.length),
  ventes: wa(total),
  marge: wa(marge),
  nonLivrees: wa(nonLivrees),
  rupture: wa(rupture.map(s => s.replace(/^- /, '')).join(', ') || 'aucun'),
  aCommander: wa(aCommander.map(s => s.replace(/^- /, '')).join(', ') || 'aucun'),
}}];
